package com.medflow.auth.config;
import com.fasterxml.jackson.databind.ObjectMapper; import com.medflow.auth.exception.ApiError; import com.medflow.auth.security.JwtAuthenticationFilter; import jakarta.servlet.http.HttpServletResponse; import java.time.Instant; import org.springframework.context.annotation.*; import org.springframework.http.HttpStatus; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.SecurityFilterChain; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;
@Configuration public class SecurityConfig {
 @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder(12);}
 @Bean SecurityFilterChain security(HttpSecurity http,JwtAuthenticationFilter jwt,ObjectMapper mapper)throws Exception{return http.csrf(c->c.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/api/auth/register","/api/auth/login","/actuator/health/**").permitAll().requestMatchers("/api/auth/staff").hasRole("ADMIN").anyRequest().authenticated()).exceptionHandling(e->e.authenticationEntryPoint((req,res,ex)->{res.setStatus(HttpServletResponse.SC_UNAUTHORIZED);res.setContentType("application/json");mapper.writeValue(res.getOutputStream(),new ApiError(Instant.now(),401,HttpStatus.UNAUTHORIZED.getReasonPhrase(),"Authentication is required",req.getRequestURI(),null));})).addFilterBefore(jwt,UsernamePasswordAuthenticationFilter.class).build();}
}
